// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User | undefined;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project | undefined;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task | undefined;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment | undefined;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
  // Internal method for creation, not on the public interface
  // create(input: { userId: string; message: string }): Notification;
}

import { EventEmitter } from 'events';
import { IEventBus } from './contracts';

export class EventBus implements IEventBus {
  private emitter = new EventEmitter();

  public publish(event: string, payload: unknown): void {
    this.emitter.emit(event, payload);
  }

  public subscribe(event: string, callback: (payload: unknown) => void): void {
    this.emitter.on(event, callback);
  }
}

import * as crypto from 'crypto';
import { User, IUserService } from './contracts';

export class UserService implements IUserService {
  private readonly users = new Map<string, User>();

  create(input: { name: string; email: string }): User {
    const id = crypto.randomUUID();
    const user: User = {
      id,
      ...input,
    };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.users.get(id);
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    if (!user) {
      throw new Error(`User with id ${id} not found`);
    }

    const updatedUser = { ...user, ...input };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  delete(id: string): void {
    if (!this.users.has(id)) {
      throw new Error(`User with id ${id} not found`);
    }
    this.users.delete(id);
  }
}

import * as crypto from 'crypto';
import { Project, IProjectService } from '../contracts';

export class ProjectService implements IProjectService {
    private readonly projects = new Map<string, Project>();

    create(input: { name: string; description: string }): Project {
        const id = crypto.randomUUID();
        const project: Project = {
            id,
            ...input,
            memberIds: [],
        };
        this.projects.set(id, project);
        return project;
    }

    getById(id: string): Project | undefined {
        return this.projects.get(id);
    }

    getAll(): Project[] {
        return Array.from(this.projects.values());
    }

    update(id: string, input: Partial<{ name: string; description: string }>): Project {
        const project = this.getById(id);
        if (!project) {
            throw new Error(`Project with id ${id} not found`);
        }

        const updatedProject = { ...project, ...input };
        this.projects.set(id, updatedProject);
        return updatedProject;
    }

    delete(id: string): void {
        if (!this.projects.has(id)) {
            throw new Error(`Project with id ${id} not found`);
        }
        this.projects.delete(id);
    }

    addMember(projectId: string, userId: string): Project {
        const project = this.getById(projectId);
        if (!project) {
            throw new Error(`Project with id ${projectId} not found`);
        }

        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
        }

        return project;
    }

    removeMember(projectId: string, userId: string): Project {
        const project = this.getById(projectId);
        if (!project) {
            throw new Error(`Project with id ${projectId} not found`);
        }

        project.memberIds = project.memberIds.filter((id) => id !== userId);
        return project;
    }
}

import * as crypto from 'crypto';
import {
    Task,
    ITaskService,
    TaskStatus,
    IEventBus,
    TaskAssignedPayload,
    TaskStatusChangedPayload
} from '../contracts';

export class TaskService implements ITaskService {
    private readonly tasks = new Map<string, Task>();

    constructor(private readonly eventBus: IEventBus) {}

    create(input: { title: string; description: string; projectId: string }): Task {
        const id = crypto.randomUUID();
        const task: Task = {
            id,
            ...input,
            status: 'todo',
            assigneeId: null,
        };
        this.tasks.set(id, task);
        return task;
    }

    getById(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    getByProject(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(
            (task) => task.projectId === projectId
        );
    }

    update(id: string, input: Partial<{ title: string; description: string }>): Task {
        const task = this.getById(id);
        if (!task) {
            throw new Error(`Task with id ${id} not found`);
        }

        const updatedTask = { ...task, ...input };
        this.tasks.set(id, updatedTask);
        return updatedTask;
    }

    delete(id: string): void {
        if (!this.tasks.has(id)) {
            throw new Error(`Task with id ${id} not found`);
        }
        this.tasks.delete(id);
    }

    assign(taskId: string, assigneeId: string): Task {
        const task = this.getById(taskId);
        if (!task) {
            throw new Error(`Task with id ${taskId} not found`);
        }

        task.assigneeId = assigneeId;

        this.eventBus.publish('task.assigned', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId,
        } as TaskAssignedPayload);

        return task;
    }

    changeStatus(taskId: string, newStatus: TaskStatus): Task {
        const task = this.getById(taskId);
        if (!task) {
            throw new Error(`Task with id ${taskId} not found`);
        }

        const oldStatus = task.status;

        // Enforce forward-only status transitions
        if (oldStatus === 'todo' && newStatus !== 'in-progress') {
            throw new Error(`Invalid status transition from todo to ${newStatus}`);
        }
        if (oldStatus === 'in-progress' && newStatus !== 'done') {
            throw new Error(`Invalid status transition from in-progress to ${newStatus}`);
        }
        if (oldStatus === 'done') {
            throw new Error(`Invalid status transition from done to ${newStatus}`);
        }
        // also handles the skipping case

        task.status = newStatus;

        this.eventBus.publish('task.statusChanged', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
            oldStatus,
            newStatus,
        } as TaskStatusChangedPayload);

        return task;
    }
}

import * as crypto from 'crypto';
import {
    Comment,
    ICommentService,
    IEventBus,
    CommentAddedPayload,
    IUserService,
    ITaskService
} from '../contracts';

export class CommentService implements ICommentService {
    private readonly comments = new Map<string, Comment>();

    constructor(
        private readonly eventBus: IEventBus,
        private readonly userService: IUserService,
        private readonly taskService: ITaskService
    ) {}

    create(input: { taskId: string; authorId: string; body: string }): Comment {
        const id = crypto.randomUUID();
        const comment: Comment = {
            id,
            ...input,
            createdAt: new Date().toISOString(),
        };
        this.comments.set(id, comment);

        const author = this.userService.getById(input.authorId);
        const task = this.taskService.getById(input.taskId);

        if (!author) {
            throw new Error(`Author with id ${input.authorId} not found`);
        }
        if (!task) {
            throw new Error(`Task with id ${input.taskId} not found`);
        }

        this.eventBus.publish('comment.added', {
            commentId: comment.id,
            taskId: task.id,
            taskTitle: task.title,
            authorId: author.id,
            authorName: author.name,
        } as CommentAddedPayload);

        return comment;
    }

    getById(id: string): Comment | undefined {
        return this.comments.get(id);
    }

    getByTask(taskId: string): Comment[] {
        return Array.from(this.comments.values()).filter(
            (comment) => comment.taskId === taskId
        );
    }

    delete(id: string): void {
        if (!this.comments.has(id)) {
            throw new Error(`Comment with id ${id} not found`);
        }
        this.comments.delete(id);
    }
}

import * as crypto from 'crypto';
import {
    Notification,
    INotificationService,
    IEventBus,
    TaskAssignedPayload,
    TaskStatusChangedPayload,
    CommentAddedPayload,
    ITaskService
} from '../contracts';

export class NotificationService implements INotificationService {
    private readonly notifications = new Map<string, Notification>();

    constructor(private readonly eventBus: IEventBus, private readonly taskService: ITaskService) {
        this.subscribeToEvents();
    }

    private subscribeToEvents(): void {
        this.eventBus.subscribe('task.assigned', (payload) => this.handleTaskAssigned(payload as TaskAssignedPayload));
        this.eventBus.subscribe('task.statusChanged', (payload) => this.handleTaskStatusChanged(payload as TaskStatusChangedPayload));
        this.eventBus.subscribe('comment.added', (payload) => this.handleCommentAdded(payload as CommentAddedPayload));
    }

    private handleTaskAssigned(payload: TaskAssignedPayload): void {
        const message = `Task '${payload.taskTitle}' has been assigned to you.`;
        this.create({ userId: payload.assigneeId, message });
    }

    private handleTaskStatusChanged(payload: TaskStatusChangedPayload): void {
        if (payload.assigneeId) {
            const message = `Task '${payload.taskTitle}' status changed from '${payload.oldStatus}' to '${payload.newStatus}'.`;
            this.create({ userId: payload.assigneeId, message });
        }
    }

    private handleCommentAdded(payload: CommentAddedPayload): void {
        const task = this.taskService.getById(payload.taskId);
        // Only notify if there is an assignee and the commenter is not the assignee
        if (task && task.assigneeId && task.assigneeId !== payload.authorId) {
            const message = `A new comment was added to task '${payload.taskTitle}' by ${payload.authorName}.`;
            this.create({ userId: task.assigneeId, message });
        }
    }

    private create(input: { userId: string; message: string }): Notification {
        const id = crypto.randomUUID();
        const notification: Notification = {
            id,
            ...input,
            read: false,
            createdAt: new Date().toISOString(),
        };
        this.notifications.set(id, notification);
        return notification;
    }

    getByUser(userId: string): Notification[] {
        return Array.from(this.notifications.values()).filter(
            (n) => n.userId === userId && !n.read
        );
    }

    markAsRead(notificationId: string): Notification {
        const notification = this.notifications.get(notificationId);
        if (!notification) {
            throw new Error(`Notification with id ${notificationId} not found`);
        }
        notification.read = true;
        return notification;
    }
}

import * as http from 'http';
import * as url from 'url';
import { IUserService, IProjectService, ITaskService, ICommentService, INotificationService } from './contracts';

// Helper to parse body
async function parseBody(req: http.IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
        let body = '';
        req.on('data', chunk => body += chunk.toString());
        req.on('end', () => {
            try {
                resolve(JSON.parse(body));
            } catch (e) {
                reject(e);
            }
        });
        req.on('error', reject);
    });
}

export class ApiRouter {
    constructor(
        private userService: IUserService,
        private projectService: IProjectService,
        private taskService: ITaskService,
        private commentService: ICommentService,
        private notificationService: INotificationService
    ) {}

    public async handle(req: http.IncomingMessage, res: http.ServerResponse) {
        const { pathname, query } = url.parse(req.url!, true);
        const method = req.method?.toUpperCase();
        res.setHeader('Content-Type', 'application/json');

        try {
            // User Routes
            if (pathname === '/users') {
                if (method === 'GET') {
                    const users = this.userService.getAll();
                    res.statusCode = 200;
                    res.end(JSON.stringify(users));
                } else if (method === 'POST') {
                    const body = await parseBody(req);
                    const user = this.userService.create(body);
                    res.statusCode = 201;
                    res.end(JSON.stringify(user));
                }
            } else if (pathname?.startsWith('/users/')) {
                const id = pathname.split('/')[2];
                if (method === 'GET') {
                    const user = this.userService.getById(id);
                    if(!user) throw new Error('User not found');
                    res.statusCode = 200;
                    res.end(JSON.stringify(user));
                } else if (method === 'PUT') {
                    const body = await parseBody(req);
                    const user = this.userService.update(id, body);
                    res.statusCode = 200;
                    res.end(JSON.stringify(user));
                } else if (method === 'DELETE') {
                    this.userService.delete(id);
                    res.statusCode = 204;
                    res.end();
                }
            }

            // Project Routes
            else if (pathname === '/projects') {
                if (method === 'GET') {
                    res.statusCode = 200;
                    res.end(JSON.stringify(this.projectService.getAll()));
                } else if (method === 'POST') {
                    const body = await parseBody(req);
                    const project = this.projectService.create(body);
                    res.statusCode = 201;
                    res.end(JSON.stringify(project));
                }
            } else if (pathname?.startsWith('/projects/')) {
                const id = pathname.split('/')[2];
                if (pathname.endsWith('/members')) {
                     const body = await parseBody(req);
                    if (method === 'POST') {
                       const project = this.projectService.addMember(id, body.userId);
                       res.statusCode = 200;
                       res.end(JSON.stringify(project));
                    } else if (method === 'DELETE') {
                       const project = this.projectService.removeMember(id, body.userId);
                       res.statusCode = 200;
                       res.end(JSON.stringify(project));
                    }
                } else {
                    if (method === 'GET') {
                        const project = this.projectService.getById(id);
                        if(!project) throw new Error('Project not found');
                        res.statusCode = 200;
                        res.end(JSON.stringify(project));
                    } else if (method === 'PUT') {
                        const body = await parseBody(req);
                        const project = this.projectService.update(id, body);
                        res.statusCode = 200;
                        res.end(JSON.stringify(project));
                    } else if (method === 'DELETE') {
                        this.projectService.delete(id);
                        res.statusCode = 204;
                        res.end();
                    }
                }
            }

            // Task Routes
            else if (pathname === '/tasks') {
                 if (method === 'GET' && query.projectId) {
                    const tasks = this.taskService.getByProject(query.projectId as string);
                    res.statusCode = 200;
                    res.end(JSON.stringify(tasks));
                } else if (method === 'POST') {
                    const body = await parseBody(req);
                    const task = this.taskService.create(body);
                    res.statusCode = 201;
                    res.end(JSON.stringify(task));
                }
            } else if (pathname?.startsWith('/tasks/')) {
                 const id = pathname.split('/')[2];
                 if (pathname.endsWith('/status')) {
                     if (method === 'PUT') {
                         const body = await parseBody(req);
                         const task = this.taskService.changeStatus(id, body.status);
                         res.statusCode = 200;
                         res.end(JSON.stringify(task));
                     }
                 } else if (pathname.endsWith('/assign')) {
                      if (method === 'PUT') {
                         const body = await parseBody(req);
                         const task = this.taskService.assign(id, body.assigneeId);
                         res.statusCode = 200;
                         res.end(JSON.stringify(task));
                      }
                 } else {
                     if (method === 'GET') {
                         const task = this.taskService.getById(id);
                         if(!task) throw new Error('Task not found');
                         res.statusCode = 200;
                         res.end(JSON.stringify(task));
                     } else if (method === 'PUT') {
                         const body = await parseBody(req);
                         const task = this.taskService.update(id, body);
                         res.statusCode = 200;
                         res.end(JSON.stringify(task));
                     } else if (method === 'DELETE') {
                         this.taskService.delete(id);
                         res.statusCode = 204;
                         res.end();
                     }
                 }
            }

            // Comment Routes
            else if (pathname === '/comments') {
                if (method === 'GET' && query.taskId) {
                    const comments = this.commentService.getByTask(query.taskId as string);
                    res.statusCode = 200;
                    res.end(JSON.stringify(comments));
                } else if (method === 'POST') {
                    const body = await parseBody(req);
                    const comment = this.commentService.create(body);
                    res.statusCode = 201;
                    res.end(JSON.stringify(comment));
                }
            } else if (pathname?.startsWith('/comments/')) {
                const id = pathname.split('/')[2];
                if (method === 'GET') {
                    const comment = this.commentService.getById(id);
                    if(!comment) throw new Error('Comment not found');
                    res.statusCode = 200;
                    res.end(JSON.stringify(comment));
                } else if (method === 'DELETE') {
                    this.commentService.delete(id);
                    res.statusCode = 204;
                    res.end();
                }
            }

            // Notification Routes
            else if (pathname === '/notifications' && query.userId) {
                if (method === 'GET') {
                    const notifications = this.notificationService.getByUser(query.userId as string);
                    res.statusCode = 200;
                    res.end(JSON.stringify(notifications));
                }
            } else if (pathname?.startsWith('/notifications/')) {
                 const id = pathname.split('/')[2];
                 if(pathname.endsWith('/read') && method === 'PUT') {
                     const notification = this.notificationService.markAsRead(id);
                     res.statusCode = 200;
                     res.end(JSON.stringify(notification));
                 }
            }

            else {
                res.statusCode = 404;
                res.end(JSON.stringify({ error: 'Not Found' }));
            }

        } catch (error: any) {
            console.error(error);
            res.statusCode = error.message.includes('not found') ? 404 : 400;
            res.end(JSON.stringify({ error: error.message }));
        }
    }
}

import * as http from 'http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { ApiRouter } from './router';

const PORT = process.env.PORT || 3000;

// 1. Initialize Event Bus
const eventBus = new EventBus();

// 2. Initialize Services
const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(eventBus);
// As per the deduction, inject services that are needed for generating event payloads
const commentService = new CommentService(eventBus, userService, taskService);
const notificationService = new NotificationService(eventBus, taskService);

// 3. Initialize Router
const router = new ApiRouter(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
);

// 4. Create and start HTTP server
const server = http.createServer((req, res) => {
    router.handle(req, res);
});

server.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});

// Export server for demo script
export { server };

import * as http from 'http';
import { server } from './main'; // Import the server to close it later

const PORT = 3000;
const BASE_URL = `http://localhost:${PORT}`;

async function request(method: string, path: string, data?: any): Promise<any> {
    return new Promise((resolve, reject) => {
        const options: http.RequestOptions = {
            method,
            path,
            headers: {
                'Content-Type': 'application/json'
            }
        };

        const req = http.request(BASE_URL + path, options, (res) => {
            let body = '';
            res.on('data', (chunk) => body += chunk);
            res.on('end', () => {
                if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
                    resolve(body ? JSON.parse(body) : null);
                } else {
                    console.error(`Request failed: ${method} ${path}`);
                    console.error(`Status: ${res.statusCode}`);
                    console.error(`Body: ${body}`);
                    reject(new Error(`Request failed with status ${res.statusCode}`));
                }
            });
        });

        req.on('error', (e) => reject(e));
        if (data) {
            req.write(JSON.stringify(data));
        }
        req.end();
    });
}

async function runDemo() {
    console.log('--- Starting API Demo ---');

    try {
        // 1. Create Users
        console.log('\n1. Creating users...');
        const user1 = await request('POST', '/users', { name: 'Alice', email: 'alice@example.com' });
        const user2 = await request('POST', '/users', { name: 'Bob', email: 'bob@example.com' });
        console.log('  -> Created:', user1.name, user2.name);

        // 2. Create Project
        console.log('\n2. Creating a project...');
        const project = await request('POST', '/projects', { name: 'Taskify', description: 'A demo project' });
        console.log('  -> Created:', project.name);

        // 3. Add members to project
        console.log('\n3. Adding members to the project...');
        await request('POST', `/projects/${project.id}/members`, { userId: user1.id });
        await request('POST', `/projects/${project.id}/members`, { userId: user2.id });
        const updatedProject = await request('GET', `/projects/${project.id}`);
        console.log('  -> Project members:', updatedProject.memberIds);

        // 4. Create tasks
        console.log('\n4. Creating tasks...');
        const task1 = await request('POST', '/tasks', { title: 'Implement UI', description: 'Design and code the frontend', projectId: project.id });
        const task2 = await request('POST', '/tasks', { title: 'Implement API', description: 'Design and code the backend', projectId: project.id });
        console.log('  -> Created tasks:', task1.title, task2.title);

        // 5. Assign task to user
        console.log('\n5. Assigning tasks...');
        await request('PUT', `/tasks/${task1.id}/assign`, { assigneeId: user1.id });
        console.log(`  -> Assigned '${task1.title}' to ${user1.name}`);

        // 6. Check notifications for user1 (Task Assigned)
        console.log(`\n6. Checking notifications for ${user1.name}...\`);
        let notifications1 = await request('GET', `/notifications?userId=${user1.id}`);
        console.log('  -> Found notifications:', notifications1.map((n: any) => n.message));
        await request('PUT', `/notifications/${notifications1[0].id}/read`, {});

        // 7. Change task status
        console.log('\n7. Changing task status...');
        await request('PUT', `/tasks/${task1.id}/status`, { status: 'in-progress' });
        console.log(`  -> Changed status of '${task1.title}' to in-progress`);

        // 8. Check notifications for user1 (Status Change)
