} from "../types";

export class NotificationService implements INotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private eventBus: IEventBus, private taskService: ITaskService) {}

  // This method should be called once in main.ts to set up subscriptions
  registerEventListeners() {
    this.eventBus.subscribe("task.assigned", (payload) => this.handleTaskAssigned(payload as TaskAssignedPayload));
    this.eventBus.subscribe("task.statusChanged", (payload) => this.handleTaskStatusChanged(payload as TaskStatusChangedPayload));
    this.eventBus.subscribe("comment.added", (payload) => this.handleCommentAdded(payload as CommentAddedPayload));
  }

  private createNotification(userId: string, message: string): Notification {
    const id = randomUUID();
    const notification: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(id, notification);
    return notification;
  }

  private handleTaskAssigned(payload: TaskAssignedPayload) {
    const { taskTitle, assigneeId } = payload;
    const message = `Task '${taskTitle}' assigned to you`;
    this.createNotification(assigneeId, message);
  }

  private handleTaskStatusChanged(payload: TaskStatusChangedPayload) {
    if (payload.assigneeId) {
      const { taskTitle, newStatus, assigneeId } = payload;
      const message = `Task '${taskTitle}' status changed to ${newStatus}`;
      this.createNotification(assigneeId, message);
    }
  }

  private handleCommentAdded(payload: CommentAddedPayload) {
    const { taskId, taskTitle, authorName } = payload;
    try {
      const task = this.taskService.getById(taskId);
      if (task.assigneeId) {
        // Don't notify the user if they are the one who commented
        if (task.assigneeId !== payload.authorId) {
           const message = `New comment on task '${taskTitle}' from ${authorName}`;
           this.createNotification(task.assigneeId, message);
        }
      }
    } catch (error) {
      console.error(`Error handling comment.added event: Task with id ${taskId} not found.`);
    }
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter(
      (n) => n.userId === userId && !n.read
    );
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.notifications.get(notificationId);
    if (!notification) {
      throw new Error(`Notification with id ${notificationId} not found`);
    }
    notification.read = true;
    this.notifications.set(notificationId, notification);
    return notification;
  }
}

